import{_ as t,o as i,c as l,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Day CERN 2019- Ceph storage for openstack in a security - Etienne Chabrerie","description":"","frontmatter":{"title":"Ceph Day CERN 2019- Ceph storage for openstack in a security - Etienne Chabrerie","date":"2020-08-25T00:00:00.000Z","updated":"2020-08-26T00:00:00.000Z","tags":["Ceph","OpenStack","分布式存储","安全性","云服务"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Day_CERN_2019_-_Ceph_storage_for_openstack_in_a_security_-_Etienne_Chabrerie.md","filePath":"posts/2020/Ceph_Day_CERN_2019_-_Ceph_storage_for_openstack_in_a_security_-_Etienne_Chabrerie.md","lastUpdated":1780459816000}'),n={name:"posts/2020/Ceph_Day_CERN_2019_-_Ceph_storage_for_openstack_in_a_security_-_Etienne_Chabrerie.md"};function s(o,e,p,a,_,g){return i(),l("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题：</strong> 法国内政部IT部门关于在OpenStack中使用Ceph存储的安全性和部署讨论</p><p><strong>参会人员：</strong> 法国内政部IT部门的DevOps团队</p><p><strong>会议时间：</strong> 下午</p><p><strong>会议地点：</strong> 线上视频会议</p><p><strong>会议内容总结：</strong></p><ol><li><p><strong>背景介绍：</strong></p><ul><li>法国内政部IT部门负责国家内部安全、警察、身份文件发放等。</li><li>该部门采用基于OpenStack的安全云服务，并寻求可扩展的存储解决方案。</li></ul></li><li><p><strong>云服务概述：</strong></p><ul><li>目前使用OpenStack和VSA存储平台，但存在性能和配置复杂性问题。</li><li>客户需要私有云环境，无法使用公共云服务。</li></ul></li><li><p><strong>技术挑战与解决方案：</strong></p><ul><li>计划部署Ceph存储，包括块存储（RBD）和对象存储（S3和Swift）。</li><li>使用SSD和NVMe存储以提高性能。</li><li>开发Ansible和SaltStack playbooks以集成外部存储。</li></ul></li><li><p><strong>实施细节：</strong></p><ul><li>提供S3服务，支持双向复制，确保数据的高可用性和灾难恢复。</li><li>使用Cobbler服务器进行节点部署，通过Ansible进行集成。</li><li>使用DeepSea进行集群发现和配置。</li></ul></li><li><p><strong>自动化与部署：</strong></p><ul><li>采用CI/CD策略，提高部署的可靠性和效率。</li><li>使用Cobbler服务器和Ansible进行自动化部署。</li></ul></li><li><p><strong>性能评估：</strong></p><ul><li>基准测试表明新系统的性能优于现有系统。</li></ul></li></ol><p><strong>后续行动计划：</strong></p><ul><li>继续推进Ceph存储系统的部署。</li><li>优化CI/CD流程，提高自动化水平。</li><li>定期进行性能评估和系统更新。</li></ul><p><strong>备注：</strong></p><ul><li>会议中提到的技术术语包括Ceph、OpenStack、VSA、SSD、NVMe、Ansible、SaltStack、DeepSea、RBD、S3、Swift、CI/CD等，体现了会议内容的专业性和技术深度。</li></ul><p><strong>会议结束时间：</strong> 未明确记录</p><p><strong>记录人：</strong> [您的姓名]</p><p><strong>审核人：</strong> [审核人姓名]</p>',14)])])}const u=t(n,[["render",s]]);export{c as __pageData,u as default};
